  "results": [
    {
      "criterion_id": "criterion-1",
      "passed": true,
      "evidence": [
        "final_message 将 30 分钟窗口和回调可能重复列为已确认事实，将沙箱、测试账号和日志查询能力列为执行前假设。",
        "final_message 明确接口字段、权限矩阵和支付最终状态规则尚未提供，并说明订单标识等只是业务概念，不预设字段名、状态枚举或错误码。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-2",
      "passed": true,
      "evidence": [
        "final_message 的 T01 覆盖登录、购物车、下单、支付及金额、库存和订单交易关联核对。",
        "final_message 的 T05、T06、T11、T12、T13 覆盖顺序及并发重复回调、非法通知、超时、失败取消和乱序通知。",
        "final_message 的 T07、T08、T09 覆盖跨账号访问、金额篡改和库存竞争。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-3",
      "passed": true,
      "evidence": [
        "final_message 给出 0–30 分钟分段执行表，按 T01、T02、T04、T05、T06、T07 和对账整理排序。",
        "final_message 明确 T03、T08–T14 默认留待补测，并要求其中未验证的 P0 列入发布风险。",
        "final_message 说明 30 分钟冒烟无法排除并发竞争、最终一致性、库存竞争、长时重试和生产配置风险。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-4",
      "passed": true,
      "evidence": [
        "final_message 的关键场景表逐项列出前置条件、操作、预期判断和证据；例如 T05 要求有效通知和可重放入口，依次投递及并发投递，并核对业务效果数量和状态历史。",
        "final_message 的 T06 规定每次只改变一个非法通知条件，并以脱敏通知、响应、日志及业务状态前后对比作为证据。",
        "final_message 规定只有操作完成、验收规则已确认且证据充分时，才可将用例记为通过。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-5",
      "passed": true,
      "evidence": [
        "final_message 开头明确这是尚未执行任何测试的初版，后文再次声明所有场景均未执行。",
        "final_message 列明重复扣款、越权、错误金额、环境误连生产及关键契约缺失时的停止或阻止放行条件。",
        "final_message 的下一步要求补齐接口契约、支付状态规则、权限矩阵和环境条件，再确认 P0 验收标准并执行验证；未宣称业务或发布已通过。"
      ],
      "failures": []
    }
  ]
}
